import type { ReactElement, ReactNode } from 'react';
import { useState } from 'react';
import type {
    ComboboxFieldOption,
    ComboboxFieldProps,
    ComboboxFieldSearchDetails,
} from '@/components/form/combobox-field';
import { ComboboxField } from '@/components/form/combobox-field';
import type { AsyncOptionsSearch } from '@/components/form/use-async-options';
import { useAsyncOptions } from '@/components/form/use-async-options';

export type AsyncComboboxFieldProps = Omit<
    ComboboxFieldProps,
    'options' | 'onSearchChange' | 'onOpenChange'
> & {
    /** Options for the typed query; see `useAsyncOptions`. */
    search: AsyncOptionsSearch<ComboboxFieldOption>;
    debounceMs?: number;
    minQueryLength?: number;
    /** Lists options as soon as the popup opens, before anything is typed. */
    loadWithoutQuery?: boolean;
    /** Changing it drops the options and searches again. */
    scope?: string | number | null;
    /** Shown while a search is running and nothing is listed yet. */
    loadingText?: ReactNode;
    /** Shown while the query is too short to search. */
    idleText?: ReactNode;
    /** Shown when the last search failed. */
    errorText?: ReactNode;
};

function mergeOptions(
    known: ComboboxFieldOption[],
    found: ComboboxFieldOption[],
): ComboboxFieldOption[] {
    const byValue = new Map(known.map((option) => [option.value, option]));

    for (const option of found) {
        byValue.set(option.value, option);
    }

    return [...byValue.values()];
}

/** Typing, or clearing what was typed; not the label a picked option writes into the input. */
function isTypedQuery(details: ComboboxFieldSearchDetails): boolean {
    if (details.isItemPress) {
        return false;
    }

    return (
        details.reason === 'input-change' ||
        details.reason === 'input-clear' ||
        details.reason === 'clear-press'
    );
}

/**
 * `ComboboxField` with options searched as the user types. The app passes
 * `search` and owns the request; the field debounces, drops superseded
 * answers, and remembers the label of every option it has seen, so a chosen
 * value keeps its label after the search moves on.
 */
export function AsyncComboboxField({
    search,
    debounceMs,
    minQueryLength,
    loadWithoutQuery = false,
    scope,
    selectedOptions,
    emptyText = 'Ничего не найдено',
    loadingText = 'Ищем…',
    idleText = 'Начните вводить',
    errorText = 'Не удалось загрузить варианты',
    ...props
}: AsyncComboboxFieldProps): ReactElement {
    const [isOpen, setIsOpen] = useState(false);
    const [seen, setSeen] = useState<ComboboxFieldOption[]>([]);

    const { options, status, setQuery } = useAsyncOptions({
        debounceMs,
        enabled: isOpen,
        loadWithoutQuery,
        minQueryLength,
        scope,
        search: (query, signal) =>
            search(query, signal).then((found) => {
                setSeen((known) => mergeOptions(known, found));

                return found;
            }),
    });

    const statusText: Record<typeof status, ReactNode> = {
        error: errorText,
        idle: idleText,
        loading: loadingText,
        success: emptyText,
    };

    return (
        <ComboboxField
            {...props}
            emptyText={statusText[status]}
            onOpenChange={(open) => {
                setIsOpen(open);

                if (!open) {
                    setQuery('');
                }
            }}
            onSearchChange={(typed, details) => {
                if (isTypedQuery(details)) {
                    setQuery(typed);
                }
            }}
            options={options}
            selectedOptions={mergeOptions(selectedOptions ?? [], seen)}
        />
    );
}

import { Checkbox } from '@/components/ui/checkbox';
import { FormField } from './form-field';
import type { FormFieldBaseProps } from './types';

export type CheckboxFieldProps = Omit<FormFieldBaseProps, 'orientation'>;

export function CheckboxField({
    name,
    label,
    labelAction,
    'aria-label': ariaLabel,
    description,
    className,
    disabled,
}: CheckboxFieldProps) {
    return (
        <FormField
            name={name}
            label={label}
            labelAction={labelAction}
            aria-label={ariaLabel}
            description={description}
            className={className}
            orientation="horizontal"
            disabled={disabled}
            controlFirst
        >
            {({ field, ...aria }) => (
                <Checkbox
                    {...aria}
                    name={field.name}
                    ref={field.ref}
                    checked={Boolean(field.value)}
                    disabled={field.disabled}
                    onBlur={field.onBlur}
                    onCheckedChange={(checked) => {
                        field.onChange(checked);
                    }}
                />
            )}
        </FormField>
    );
}

import type { ReactNode } from 'react';
import type { ComboboxPrimitive } from '@/components/ui/combobox';
import {
    Combobox,
    ComboboxChip,
    ComboboxChips,
    ComboboxChipsInput,
    ComboboxEmpty,
    ComboboxInput,
    ComboboxItem,
    ComboboxList,
    ComboboxPopup,
    ComboboxValue,
} from '@/components/ui/combobox';
import { FormField } from './form-field';
import type { FieldControlProps, FormFieldBaseProps } from './types';

export type ComboboxFieldOption = {
    value: string;
    label: string;
    description?: string;
    disabled?: boolean;
};

/** Why the typed text changed: `input-change` is typing, `item-press` is the label of a picked option. */
export type ComboboxFieldSearchDetails =
    ComboboxPrimitive.Root.ChangeEventDetails;

export type ComboboxFieldProps = FormFieldBaseProps & {
    options: ComboboxFieldOption[];
    selectedOptions?: ComboboxFieldOption[];
    multiple?: boolean;
    placeholder?: string;
    emptyText?: ReactNode;
    onSearchChange?: (
        query: string,
        details: ComboboxFieldSearchDetails,
    ) => void;
    onOpenChange?: (open: boolean) => void;
};

function optionLabel(option: ComboboxFieldOption): string {
    return option.label;
}

function isSameOption(
    option: ComboboxFieldOption,
    value: ComboboxFieldOption,
): boolean {
    return option.value === value.value;
}

function OptionRows({ emptyText }: { emptyText: ReactNode }) {
    return (
        <ComboboxPopup>
            <ComboboxEmpty>{emptyText}</ComboboxEmpty>
            <ComboboxList>
                {(option: ComboboxFieldOption) => (
                    <ComboboxItem
                        disabled={option.disabled}
                        key={option.value}
                        value={option}
                    >
                        <span>{option.label}</span>
                        {option.description ? (
                            <span className="block text-muted-foreground text-xs">
                                {option.description}
                            </span>
                        ) : null}
                    </ComboboxItem>
                )}
            </ComboboxList>
        </ComboboxPopup>
    );
}

function ChipsControl({
    aria,
    placeholder,
    inputRef,
    onBlur,
}: {
    aria: FieldControlProps;
    placeholder?: string;
    inputRef: (element: HTMLInputElement | null) => void;
    onBlur: () => void;
}) {
    return (
        <ComboboxChips>
            <ComboboxValue>
                {(selected: ComboboxFieldOption[]) => (
                    <>
                        {selected.map((option) => (
                            <ComboboxChip
                                key={option.value}
                                removeProps={{
                                    'aria-label': `Убрать «${option.label}»`,
                                }}
                            >
                                {option.label}
                            </ComboboxChip>
                        ))}
                        <ComboboxChipsInput
                            {...aria}
                            onBlur={onBlur}
                            placeholder={
                                selected.length === 0 ? placeholder : undefined
                            }
                            ref={inputRef}
                        />
                    </>
                )}
            </ComboboxValue>
        </ComboboxChips>
    );
}

export function ComboboxField({
    name,
    label,
    labelAction,
    'aria-label': ariaLabel,
    description,
    className,
    orientation,
    disabled,
    options,
    selectedOptions,
    multiple = false,
    placeholder,
    emptyText = 'Ничего не найдено',
    onSearchChange,
    onOpenChange,
}: ComboboxFieldProps) {
    const known = new Map(
        [...(selectedOptions ?? []), ...options].map((option) => [
            option.value,
            option,
        ]),
    );

    const toOption = (value: string): ComboboxFieldOption =>
        known.get(value) ?? { label: value, value };

    const shared = {
        filter: onSearchChange ? null : undefined,
        isItemEqualToValue: isSameOption,
        itemToStringLabel: optionLabel,
        items: options,
        onInputValueChange: onSearchChange,
        onOpenChange: onOpenChange
            ? (open: boolean) => onOpenChange(open)
            : undefined,
    };

    return (
        <FormField
            name={name}
            label={label}
            labelAction={labelAction}
            aria-label={ariaLabel}
            description={description}
            className={className}
            orientation={orientation}
            disabled={disabled}
        >
            {({ field, ...aria }) =>
                multiple ? (
                    <Combobox
                        {...shared}
                        disabled={field.disabled}
                        multiple
                        onValueChange={(selected: ComboboxFieldOption[]) =>
                            field.onChange(
                                selected.map((option) => option.value),
                            )
                        }
                        value={((field.value ?? []) as string[]).map(toOption)}
                    >
                        <ChipsControl
                            aria={aria}
                            inputRef={field.ref}
                            onBlur={field.onBlur}
                            placeholder={placeholder}
                        />
                        <OptionRows emptyText={emptyText} />
                    </Combobox>
                ) : (
                    <Combobox
                        {...shared}
                        disabled={field.disabled}
                        onValueChange={(selected: ComboboxFieldOption | null) =>
                            field.onChange(selected?.value ?? '')
                        }
                        value={field.value ? toOption(field.value) : null}
                    >
                        <ComboboxInput
                            {...aria}
                            onBlur={field.onBlur}
                            placeholder={placeholder}
                            ref={field.ref}
                            showClear={Boolean(field.value)}
                            clearProps={{ 'aria-label': 'Очистить' }}
                        />
                        <OptionRows emptyText={emptyText} />
                    </Combobox>
                )
            }
        </FormField>
    );
}

import { format, isValid, parse } from 'date-fns';
import { CalendarIcon } from 'lucide-react';
import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Calendar } from '@/components/ui/calendar';
import {
    Popover,
    PopoverContent,
    PopoverTrigger,
} from '@/components/ui/popover';
import { cn } from '@/lib/utils';
import { FormField } from './form-field';
import type { FormFieldBaseProps } from './types';

/**
 * The value stored in form state is a `yyyy-MM-dd` string, never a Date.
 * A Date would be serialised in the browser's timezone and can arrive at
 * Laravel as the previous day.
 */
const VALUE_FORMAT = 'yyyy-MM-dd';

function toDate(value: unknown): Date | undefined {
    if (typeof value !== 'string' || value === '') {
        return undefined;
    }

    const parsed = parse(value, VALUE_FORMAT, new Date());

    return isValid(parsed) ? parsed : undefined;
}

export type DateFieldProps = FormFieldBaseProps & {
    placeholder?: string;
    /** How the chosen day is shown on the trigger. The stored value stays `yyyy-MM-dd`. */
    displayFormat?: string;
    triggerClassName?: string;
};

export function DateField({
    name,
    label,
    labelAction,
    'aria-label': ariaLabel,
    description,
    className,
    orientation,
    disabled,
    placeholder = 'Pick a date',
    displayFormat = 'PPP',
    triggerClassName,
}: DateFieldProps) {
    const [open, setOpen] = useState(false);

    return (
        <FormField
            name={name}
            label={label}
            labelAction={labelAction}
            aria-label={ariaLabel}
            description={description}
            className={className}
            orientation={orientation}
            disabled={disabled}
        >
            {({ field, ...aria }) => {
                const selected = toDate(field.value);

                return (
                    <Popover open={open} onOpenChange={setOpen}>
                        <PopoverTrigger
                            render={
                                <Button
                                    {...aria}
                                    ref={field.ref}
                                    type="button"
                                    variant="outline"
                                    disabled={field.disabled}
                                    onBlur={field.onBlur}
                                    className={cn(
                                        'w-full justify-start font-normal',
                                        !selected && 'text-muted-foreground',
                                        triggerClassName,
                                    )}
                                >
                                    <CalendarIcon />
                                    {selected
                                        ? format(selected, displayFormat)
                                        : placeholder}
                                </Button>
                            }
                        />

                        <PopoverContent className="w-auto p-0" align="start">
                            <Calendar
                                mode="single"
                                autoFocus
                                selected={selected}
                                defaultMonth={selected}
                                onSelect={(date) => {
                                    field.onChange(
                                        date ? format(date, VALUE_FORMAT) : '',
                                    );
                                    setOpen(false);
                                }}
                            />
                        </PopoverContent>
                    </Popover>
                );
            }}
        </FormField>
    );
}

import { ImagePlus } from 'lucide-react';
import type {
    ChangeEvent,
    DragEvent,
    ReactElement,
    ReactNode,
    Ref,
} from 'react';
import { useState } from 'react';
import { buttonVariants } from '@/components/ui/button';
import { cn } from '@/lib/utils';

export type DropzoneSize = 'default' | 'compact';

export type DropzoneProps = {
    /** Receives the files dropped or picked; the zone itself keeps nothing. */
    onFiles: (files: File[]) => void;
    /** Narrows the file picker. Dropped files are not filtered: the caller checks them. */
    accept?: string;
    multiple?: boolean;
    disabled?: boolean;
    invalid?: boolean;
    /**
     * `default` is a wide block with a hint and a button; `compact` is a small
     * tile that sits next to a row of thumbnails.
     */
    size?: DropzoneSize;
    /** Defaults to an image icon. */
    icon?: ReactNode;
    /** The hint of the `default` size, replaced while files are dragged over. */
    hint?: ReactNode;
    draggingHint?: ReactNode;
    /** The text of the button, or of the link in a `compact` tile. */
    buttonLabel?: ReactNode;
    /** Rendered under the button, e.g. «3 из 10». */
    children?: ReactNode;
    /** Points a field label at the file input. */
    inputId?: string;
    inputRef?: Ref<HTMLInputElement>;
    onBlur?: () => void;
    'aria-describedby'?: string;
    'aria-invalid'?: boolean;
    'aria-label'?: string;
    className?: string;
};

/**
 * Where files are dropped or picked. The file input stays in the tab order
 * (visually hidden, its label styled as the button), so the field label,
 * description and error reach it as they reach any other control.
 */
export function Dropzone({
    onFiles,
    accept,
    multiple = true,
    disabled = false,
    invalid = false,
    size = 'default',
    icon,
    hint = 'Перетащите файлы сюда или',
    draggingHint = 'Отпустите, чтобы добавить',
    buttonLabel = size === 'compact' ? 'Добавить' : 'Выберите файлы',
    children,
    inputId,
    inputRef,
    onBlur,
    'aria-describedby': describedBy,
    'aria-invalid': ariaInvalid,
    'aria-label': ariaLabel,
    className,
}: DropzoneProps): ReactElement {
    const [isDragging, setIsDragging] = useState(false);
    const isCompact = size === 'compact';

    const pick = (event: ChangeEvent<HTMLInputElement>): void => {
        const files = [...(event.target.files ?? [])];

        event.target.value = '';

        if (files.length > 0) {
            onFiles(files);
        }
    };

    const drop = (event: DragEvent<HTMLDivElement>): void => {
        event.preventDefault();
        setIsDragging(false);

        const files = [...event.dataTransfer.files];

        if (!disabled && files.length > 0) {
            onFiles(multiple ? files : files.slice(0, 1));
        }
    };

    const input = (
        <input
            accept={accept}
            aria-describedby={describedBy}
            aria-invalid={ariaInvalid || invalid || undefined}
            aria-label={ariaLabel}
            className="sr-only"
            disabled={disabled}
            id={inputId}
            multiple={multiple}
            onBlur={onBlur}
            onChange={pick}
            ref={inputRef}
            type="file"
        />
    );

    return (
        // biome-ignore lint/a11y/noStaticElementInteractions: a drop zone; the file input inside is the keyboard path
        <div
            className={cn(
                'flex flex-col items-center justify-center rounded-xl border border-dashed text-center transition-[color,background-color,border-color,box-shadow] has-[input:focus-visible]:border-ring has-[input:focus-visible]:ring-[3px] has-[input:focus-visible]:ring-ring/24',
                isCompact
                    ? 'h-24 w-36 shrink-0 gap-1.5'
                    : 'w-full gap-3 px-4 py-8',
                isDragging && 'border-ring bg-accent/40',
                invalid && 'border-destructive/48',
                disabled && 'opacity-64',
                className,
            )}
            data-dragging={isDragging || undefined}
            data-slot="dropzone"
            onDragLeave={() => {
                setIsDragging(false);
            }}
            onDragOver={(event) => {
                event.preventDefault();
                setIsDragging(!disabled);
            }}
            onDrop={drop}
        >
            <span
                aria-hidden="true"
                className={cn(
                    'text-muted-foreground [&_svg]:pointer-events-none',
                    isCompact
                        ? '[&_svg:not([class*=size-])]:size-5'
                        : '[&_svg:not([class*=size-])]:size-6',
                )}
            >
                {icon ?? <ImagePlus />}
            </span>

            {isCompact ? null : (
                <p className="text-muted-foreground text-sm">
                    {isDragging ? draggingHint : hint}
                </p>
            )}

            <label
                className={cn(
                    isCompact
                        ? 'font-medium text-xs underline underline-offset-4'
                        : buttonVariants({ size: 'sm', variant: 'outline' }),
                    disabled ? 'cursor-not-allowed' : 'cursor-pointer',
                )}
                htmlFor={inputId}
            >
                {buttonLabel}
                {input}
            </label>

            {children}
        </div>
    );
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
    return (
        typeof value === 'object' &&
        value !== null &&
        !Array.isArray(value) &&
        Object.getPrototypeOf(value) === Object.prototype
    );
}

/**
 * Flattens the form's default values into the set of paths a field may bind to.
 * Arrays contribute only their own key, since their indices are not known upfront.
 */
export function collectFieldPaths(
    values: unknown,
    prefix = '',
    paths = new Set<string>(),
): Set<string> {
    if (!isPlainObject(values)) {
        return paths;
    }

    for (const [key, value] of Object.entries(values)) {
        const path = prefix ? `${prefix}.${key}` : key;

        paths.add(path);
        collectFieldPaths(value, path, paths);
    }

    return paths;
}

/** Paths that walk into an array are accepted whenever their root key exists. */
export function isKnownFieldPath(paths: Set<string>, name: string): boolean {
    if (paths.has(name)) {
        return true;
    }

    if (/\.\d+(\.|$)/.test(name)) {
        return paths.has(name.split('.')[0]);
    }

    return false;
}

import { Link } from '@inertiajs/react';
import type { ComponentProps, ReactElement, ReactNode } from 'react';
import { useFormContext } from 'react-hook-form';
import type { ButtonProps } from '@/components/ui/button';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';

export type FormActionsAlign = 'start' | 'end';

export type FormActionsProps = {
    submitLabel: ReactNode;
    /**
     * `start` (page forms): submit, then a ghost cancel link.
     * `end` (dialogs and sheets): cancel, then submit, pushed to the end.
     */
    align?: FormActionsAlign;
    cancelLabel?: ReactNode;
    /** Where cancel leads; a Wayfinder route or a URL. Rendered as an Inertia `Link`. */
    cancelHref?: ComponentProps<typeof Link>['href'];
    /** Cancel as a button, e.g. closing a dialog. Ignored when `cancelHref` is set. */
    onCancel?: () => void;
    /** Defaults to `formState.isSubmitting`. */
    pending?: boolean;
    disabled?: boolean;
    submitVariant?: ButtonProps['variant'];
    /** Defaults to `ghost` for `start` and `secondary` for `end`. */
    cancelVariant?: ButtonProps['variant'];
    className?: string;
};

/**
 * The footer of a form: its submit button, which shows a spinner and stays
 * disabled while the form is sent, and an optional way back. Without
 * `cancelHref` or `onCancel` there is no cancel button.
 */
export function FormActions({
    submitLabel,
    align = 'start',
    cancelLabel = 'Отмена',
    cancelHref,
    onCancel,
    pending,
    disabled = false,
    submitVariant = 'default',
    cancelVariant = align === 'start' ? 'ghost' : 'secondary',
    className,
}: FormActionsProps): ReactElement {
    const { formState } = useFormContext();
    const isPending = pending ?? formState.isSubmitting;

    const submit = (
        <Button
            disabled={disabled}
            loading={isPending}
            type="submit"
            variant={submitVariant}
        >
            {submitLabel}
        </Button>
    );

    let cancel: ReactNode = null;

    if (cancelHref !== undefined) {
        cancel = (
            <Button render={<Link href={cancelHref} />} variant={cancelVariant}>
                {cancelLabel}
            </Button>
        );
    } else if (onCancel) {
        cancel = (
            <Button
                disabled={isPending}
                onClick={onCancel}
                type="button"
                variant={cancelVariant}
            >
                {cancelLabel}
            </Button>
        );
    }

    return (
        <div
            className={cn(
                'flex flex-wrap items-center gap-2',
                align === 'end' && 'justify-end',
                className,
            )}
            data-slot="form-actions"
        >
            {align === 'start' ? submit : cancel}
            {align === 'start' ? cancel : submit}
        </div>
    );
}

import { createContext } from 'react';

/**
 * Paths the surrounding form knows about, derived from its default values.
 * `null` when no form provides it, which switches the dev-time name check off.
 */
export const FieldPathsContext = createContext<Set<string> | null>(null);

import type { ReactNode } from 'react';
import { useContext, useEffect, useId } from 'react';
import { Controller, useFormContext } from 'react-hook-form';
import {
    Field,
    FieldDescription,
    FieldError,
    FieldLabel,
} from '@/components/ui/field';
import { cn } from '@/lib/utils';
import { isKnownFieldPath } from './field-paths';
import { FieldPathsContext } from './form-context';
import type {
    FieldOrientation,
    FormFieldBaseProps,
    FormFieldRenderArgs,
} from './types';

/**
 * Base UI's Field.Root is a plain column and has no `orientation` prop, so the
 * variants the form primitives were built against live here. Keeping them out
 * of `ui/field.tsx` means a registry resync cannot drop them again.
 */
const orientationClassName: Record<FieldOrientation, string> = {
    vertical: '',
    horizontal: 'flex-row items-center *:data-[slot=field-label]:flex-auto',
    responsive:
        'sm:flex-row sm:items-center sm:*:data-[slot=field-label]:flex-auto',
};

export type FormFieldProps = FormFieldBaseProps & {
    /**
     * Renders the control and nothing else. The label, description, error and
     * aria wiring around it belong to FormField.
     */
    children: (args: FormFieldRenderArgs) => ReactNode;
    /** Places the control before its label, as checkboxes and switches expect. */
    controlFirst?: boolean;
};

/**
 * `name` is typed as a plain string, so a typo cannot be caught by the compiler.
 * This checks it against the paths derived from the form's default values and
 * fails loudly in development instead of silently leaving the field unbound.
 */
function useKnownFieldName(name: string): void {
    const fieldPaths = useContext(FieldPathsContext);

    useEffect(() => {
        if (
            !import.meta.env.DEV ||
            fieldPaths === null ||
            isKnownFieldPath(fieldPaths, name)
        ) {
            return;
        }

        throw new Error(
            `FormField: field "${name}" is not part of the form schema. Available paths: ${[...fieldPaths].sort().join(', ')}.`,
        );
    }, [fieldPaths, name]);
}

export function FormField({
    name,
    label,
    labelAction,
    'aria-label': ariaLabel,
    description,
    className,
    orientation,
    disabled,
    controlFirst = false,
    children,
}: FormFieldProps) {
    const { control } = useFormContext();
    const generatedId = useId();

    useKnownFieldName(name);

    const id = `${name}-${generatedId}`;
    const descriptionId = `${id}-description`;
    const errorId = `${id}-error`;

    return (
        <Controller
            control={control}
            name={name}
            disabled={disabled}
            render={({ field, fieldState }) => {
                const invalid = Boolean(fieldState.error);
                const describedBy =
                    [
                        description ? descriptionId : null,
                        invalid ? errorId : null,
                    ]
                        .filter(Boolean)
                        .join(' ') || undefined;

                const controlNode = children({
                    field,
                    id,
                    'aria-invalid': invalid || undefined,
                    'aria-describedby': describedBy,
                    'aria-label': ariaLabel,
                });

                const fieldLabel = label ? (
                    <FieldLabel htmlFor={id}>{label}</FieldLabel>
                ) : null;

                // `w-full` is what lets the action sit at the far edge: Field
                // is `items-start`, so without it this row shrinks to its own
                // content and there is no free space to justify against.
                const labelNode =
                    fieldLabel && labelAction ? (
                        <div className="flex w-full items-center justify-between gap-2">
                            {fieldLabel}
                            {labelAction}
                        </div>
                    ) : (
                        fieldLabel
                    );

                return (
                    <Field
                        className={cn(
                            orientationClassName[orientation ?? 'vertical'],
                            className,
                        )}
                        invalid={invalid}
                    >
                        {controlFirst ? controlNode : labelNode}
                        {controlFirst ? labelNode : controlNode}

                        {description ? (
                            <FieldDescription id={descriptionId}>
                                {description}
                            </FieldDescription>
                        ) : null}

                        {invalid ? (
                            <FieldError id={errorId} match>
                                {fieldState.error?.message}
                            </FieldError>
                        ) : null}
                    </Field>
                );
            }}
        />
    );
}

import type { ComponentProps, ReactNode } from 'react';
import type { FieldErrors, FieldValues } from 'react-hook-form';
import { FormProvider } from 'react-hook-form';
import type { ZodType } from 'zod';
import AlertError from '@/components/common/alert-error';
import { FieldPathsContext } from './form-context';
import type {
    InertiaFormReturn,
    SchemaInput,
    SchemaOutput,
    UseInertiaFormOptions,
} from './use-inertia-form';
import { useInertiaForm } from './use-inertia-form';

type FormElementProps = Omit<
    ComponentProps<'form'>,
    'onSubmit' | 'action' | 'method' | 'children'
>;

type FormChildren<TInput extends FieldValues, TOutput> =
    | ReactNode
    | ((form: InertiaFormReturn<TInput, TOutput>) => ReactNode);

type ProvidedFormProps<
    TInput extends FieldValues,
    TOutput,
> = FormElementProps & {
    /** An existing form from `useInertiaForm`, for pages that need its methods outside the markup. */
    form: InertiaFormReturn<TInput, TOutput>;
    children: FormChildren<TInput, TOutput>;
};

type ManagedFormProps<TSchema extends ZodType<unknown, FieldValues>> =
    FormElementProps &
        UseInertiaFormOptions<TSchema> & {
            form?: undefined;
            children: FormChildren<SchemaInput<TSchema>, SchemaOutput<TSchema>>;
        };

export type FormProps<
    TSchema extends ZodType<unknown, FieldValues>,
    TInput extends FieldValues,
    TOutput,
> = ProvidedFormProps<TInput, TOutput> | ManagedFormProps<TSchema>;

/** Server errors that matched no field are stored under `root` and surfaced as one alert. */
function collectRootErrors(errors: FieldErrors): string[] {
    if (!errors.root) {
        return [];
    }

    return Object.values(
        errors.root as unknown as Record<string, { message?: unknown }>,
    )
        .map((error) =>
            typeof error?.message === 'string' ? error.message : null,
        )
        .filter((message): message is string => message !== null);
}

function FormShell<TInput extends FieldValues, TOutput>({
    form,
    children,
    ...formProps
}: ProvidedFormProps<TInput, TOutput>) {
    const { submit, fieldPaths, ...methods } = form;
    const rootErrors = collectRootErrors(methods.formState.errors);

    return (
        <FieldPathsContext.Provider value={fieldPaths}>
            <FormProvider {...methods}>
                <form {...formProps} onSubmit={submit} noValidate>
                    {rootErrors.length > 0 ? (
                        <AlertError errors={rootErrors} />
                    ) : null}

                    {typeof children === 'function' ? children(form) : children}
                </form>
            </FormProvider>
        </FieldPathsContext.Provider>
    );
}

function ManagedForm<TSchema extends ZodType<unknown, FieldValues>>({
    action,
    schema,
    defaultValues,
    resetOnSuccess,
    transform,
    onSuccess,
    onError,
    visit,
    mode,
    reValidateMode,
    ...formProps
}: ManagedFormProps<TSchema>) {
    const form = useInertiaForm<TSchema>({
        action,
        schema,
        defaultValues,
        resetOnSuccess,
        transform,
        onSuccess,
        onError,
        visit,
        mode,
        reValidateMode,
    });

    return <FormShell {...formProps} form={form} />;
}

/**
 * Renders the form element, provides the react-hook-form context and shows any
 * server error that belongs to no field. Creates the form itself unless one is
 * passed in.
 */
export function Form<
    TSchema extends ZodType<unknown, FieldValues>,
    TInput extends FieldValues = SchemaInput<TSchema>,
    TOutput = SchemaOutput<TSchema>,
>(props: FormProps<TSchema, TInput, TOutput>) {
    if (props.form) {
        return <FormShell {...props} />;
    }

    return <ManagedForm {...props} />;
}

const fractionFormatter = new Intl.NumberFormat('ru-RU', {
    maximumFractionDigits: 2,
});

/**
 * A file size as people read it: «840 КБ», «1,5 МБ». Anything under a
 * kilobyte still reads as «1 КБ», so a tiny file never shows as empty.
 */
export function formatFileSize(bytes: number): string {
    return bytes >= 1024 * 1024
        ? `${fractionFormatter.format(bytes / 1024 / 1024)} МБ`
        : `${Math.max(1, Math.round(bytes / 1024))} КБ`;
}

