type MediaControlProps<TItem> = Required<
    Pick<MediaFieldItemAdapter<TItem>, 'getKey' | 'getName'>
> &
    Pick<
        MediaFieldItemAdapter<TItem>,
        'getPreviewUrl' | 'getSize' | 'getHref'
    > & {
        items: (File | TItem)[];
        onChange: (items: (File | TItem)[]) => void;
        onBlur: () => void;
        inputRef: Ref<HTMLInputElement>;
        variant: MediaFieldVariant;
        accept?: string;
        maxSize: number;
        maxFiles?: number;
        cover: boolean;
        coverLabel: string;
        reorderable: boolean;
        dropzoneSize: DropzoneSize;
        dropzoneHint?: ReactNode;
        disabled: boolean;
        inputId: string;
        describedBy?: string;
        ariaLabel?: string;
        invalid?: boolean;
    };

function MediaControl<TItem>({
    items,
    onChange,
    onBlur,
    inputRef,
    variant,
    accept,
    maxSize,
    maxFiles,
    cover,
    coverLabel,
    reorderable,
    dropzoneSize,
    dropzoneHint,
    disabled,
    inputId,
    describedBy,
    ariaLabel,
    invalid,
    getKey,
    getName,
    getPreviewUrl,
    getSize,
    getHref,
}: MediaControlProps<TItem>): ReactElement {
    const [rejected, setRejected] = useState<string[]>([]);
    const rejectedId = useId();
    const isImageVariant = variant === 'image';
    const filePreviews = useFilePreviews(items, isImageVariant);

    const keyOf = (item: File | TItem): string =>
        item instanceof File ? fileKey(item) : getKey(item);

    const keys = uniqueKeys(items.map(keyOf));

    const previewOf = (item: File | TItem): string | null =>
        item instanceof File
            ? (filePreviews.get(item) ?? null)
            : ((getPreviewUrl ?? defaultUrl)(item) ?? null);

    const views: ItemView[] = items.map((item, index) =>
        item instanceof File
            ? {
                  href: null,
                  key: keys[index],
                  name: item.name,
                  size: item.size,
              }
            : {
                  href: (getHref ?? defaultUrl)(item) ?? null,
                  key: keys[index],
                  name: getName(item),
                  size: (getSize ?? defaultSize)(item) ?? null,
              },
    );

    const add = (incoming: File[]): void => {
        const problems: string[] = [];
        const known = new Set(items.map(keyOf));

        const kept = incoming.filter((file) => {
            if (isImageVariant && !isImage(file)) {
                problems.push(`${file.name} — не изображение`);

                return false;
            }

            if (accept && !matchesAccept(file, accept)) {
                problems.push(`${file.name} — неподходящий формат`);

                return false;
            }

            if (file.size > maxSize) {
                problems.push(
                    `${file.name} — больше ${formatFileSize(maxSize)}`,
                );

                return false;
            }

            // The same file picked twice is added once.
            if (known.has(fileKey(file))) {
                return false;
            }

            known.add(fileKey(file));

            return true;
        });

        const room =
            maxFiles === undefined
                ? kept.length
                : Math.max(maxFiles - items.length, 0);

        if (kept.length > room) {
            problems.push(`Не больше ${maxFiles} — лишние файлы не добавлены`);
        }

        setRejected(problems);

        if (room > 0 && kept.length > 0) {
            onChange([...items, ...kept.slice(0, room)]);
        }
    };

    const move = (from: number, to: number): void => {
        onChange(moveItem(items, from, to));
    };

    const remove = (index: number): void => {
        onChange(items.filter((_, position) => position !== index));
    };

    const isFull = maxFiles !== undefined && items.length >= maxFiles;
    const isCompact = dropzoneSize === 'compact';

    const actionProps = {
        count: items.length,
        cover,
        disabled,
        onMove: move,
        onRemove: remove,
        reorderable,
        variant,
    };

    const dropzone = (
        <Dropzone
            accept={accept}
            aria-describedby={rejected.length > 0 ? rejectedId : describedBy}
            aria-label={ariaLabel}
            buttonLabel={
                isFull
                    ? 'Лимит достигнут'
                    : isCompact
                      ? 'Добавить'
                      : 'Выберите файлы'
            }
            disabled={disabled || isFull}
            hint={dropzoneHint}
            icon={isImageVariant ? undefined : <FileText />}
            inputId={inputId}
            inputRef={inputRef}
            invalid={invalid}
            multiple={maxFiles !== 1}
            onBlur={onBlur}
            onFiles={add}
            size={dropzoneSize}
        >
            {items.length > 0 && maxFiles !== undefined ? (
                <span className="text-[0.6875rem] text-muted-foreground">
                    {items.length} из {maxFiles}
                </span>
            ) : null}
        </Dropzone>
    );

    const list =
        items.length === 0 ? null : isImageVariant ? (
            <AttachmentGroup
                className={cn('min-w-0 py-0', isCompact && 'flex-1')}
            >
                {views.map((view, index) => (
                    <ImageTile
                        {...actionProps}
                        coverLabel={coverLabel}
                        index={index}
                        key={view.key}
                        preview={previewOf(items[index])}
                        view={view}
                    />
                ))}
            </AttachmentGroup>
        ) : (
            <ul className="flex w-full flex-col gap-2">
                {views.map((view, index) => (
                    <li key={view.key}>
                        <FileRow
                            {...actionProps}
                            coverLabel={coverLabel}
                            index={index}
                            view={view}
                        />
                    </li>
                ))}
            </ul>
        );

    return (
        <div className="flex w-full flex-col gap-2">
            {isCompact ? (
                <div className="flex items-start gap-3">
                    {dropzone}
                    {list}
                </div>
            ) : (
                <>
                    {list}
                    {dropzone}
                </>
            )}

            {rejected.length > 0 ? (
                <ul
                    className="flex flex-col gap-1 text-destructive text-xs"
                    id={rejectedId}
                    role="alert"
                >
                    {rejected.map((problem) => (
                        <li key={problem}>{problem}</li>
                    ))}
                </ul>
            ) : null}
        </div>
    );
}

/**
 * Images or documents of a form, kept in form state as one ordered list:
 * items the server already has (URLs, or records read through the adapter
 * getters) next to `File`s picked to add. Removing, reordering and adding all
 * travel with the form.
 */
export function MediaField<TItem = string>({
    name,
    label,
    labelAction,
    'aria-label': ariaLabel,
    description,
    className,
    orientation,
    disabled,
    variant = 'image',
    accept = variant === 'image' ? DEFAULT_IMAGE_ACCEPT : undefined,
    maxSize = DEFAULT_MAX_SIZE,
    maxFiles,
    cover = variant === 'image',
    coverLabel = 'Обложка',
    reorderable = false,
    dropzoneSize = variant === 'image' ? 'compact' : 'default',
    dropzoneHint,
    getKey = defaultKey,
    getName = defaultName,
    getPreviewUrl,
    getSize,
    getHref,
}: MediaFieldProps<TItem>): ReactElement {
    return (
        <FormField
            aria-label={ariaLabel}
            className={className}
            description={description}
            disabled={disabled}
            label={label}
            labelAction={labelAction}
            name={name}
            orientation={orientation}
        >
            {({ field, ...aria }) => (
                <MediaControl<TItem>
                    accept={accept}
                    ariaLabel={aria['aria-label']}
                    cover={cover}
                    coverLabel={coverLabel}
                    describedBy={aria['aria-describedby']}
                    disabled={Boolean(field.disabled)}
                    dropzoneHint={dropzoneHint}
                    dropzoneSize={dropzoneSize}
                    getHref={getHref}
                    getKey={getKey}
                    getName={getName}
                    getPreviewUrl={getPreviewUrl}
                    getSize={getSize}
                    inputId={aria.id}
                    inputRef={field.ref}
                    invalid={aria['aria-invalid']}
                    items={Array.isArray(field.value) ? field.value : []}
                    maxFiles={maxFiles}
                    maxSize={maxSize}
                    onBlur={field.onBlur}
                    onChange={field.onChange}
                    reorderable={reorderable}
                    variant={variant}
                />
            )}
        </FormField>
    );
}

import { Field as FieldPrimitive } from '@base-ui/react/field';
import type { ReactElement } from 'react';
import { useController, useFormContext } from 'react-hook-form';
import { FormField } from '@/components/form/form-field';
import type { FormFieldBaseProps } from '@/components/form/types';
import {
    InputGroup,
    InputGroupAddon,
    InputGroupInput,
} from '@/components/ui/input-group';
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from '@/components/ui/select';

export type MoneyFieldCurrency = {
    value: string;
    label: string;
};

export type MoneyFieldProps = FormFieldBaseProps & {
    /** Path of the amount. It is held as typed («85 000», «12,5»); the schema parses it. */
    name: string;
    /** Path of the currency code, e.g. `currency` or `price.currency`. */
    currencyName: string;
    currencies: MoneyFieldCurrency[];
    placeholder?: string;
    /** Names the currency select, which has no visible label. */
    currencyLabel?: string;
    currencyPlaceholder?: string;
};

function CurrencySelect({
    name,
    currencies,
    label,
    placeholder,
    disabled,
}: {
    name: string;
    currencies: MoneyFieldCurrency[];
    label: string;
    placeholder?: string;
    disabled?: boolean;
}): ReactElement {
    const { control } = useFormContext();
    const { field, fieldState } = useController({ control, disabled, name });

    // A Field of its own: inside the amount's Field the select would register
    // as that field's control and take over the amount input's id and label.
    return (
        <FieldPrimitive.Root
            invalid={Boolean(fieldState.error)}
            render={<InputGroupAddon align="inline-end" />}
        >
            <Select
                disabled={field.disabled}
                items={currencies}
                onValueChange={(value) => {
                    field.onChange(value);
                }}
                value={field.value ?? ''}
            >
                <SelectTrigger
                    aria-invalid={fieldState.error ? true : undefined}
                    aria-label={label}
                    className="w-auto min-w-0 border-0 bg-transparent px-2 shadow-none ring-0 before:hidden dark:bg-transparent"
                    onBlur={field.onBlur}
                    ref={field.ref}
                    size="sm"
                >
                    <SelectValue placeholder={placeholder} />
                </SelectTrigger>

                <SelectContent alignItemWithTrigger={false}>
                    {currencies.map((currency) => (
                        <SelectItem key={currency.value} value={currency.value}>
                            {currency.label}
                        </SelectItem>
                    ))}
                </SelectContent>
            </Select>
        </FieldPrimitive.Root>
    );
}

/**
 * An amount and its currency in one input group, bound to two form paths.
 * Label, description and error belong to the amount; a rejected currency
 * marks its select as invalid. Give the currency a default in the schema.
 */
export function MoneyField({
    name,
    currencyName,
    currencies,
    placeholder,
    currencyLabel = 'Валюта',
    currencyPlaceholder,
    disabled,
    ...props
}: MoneyFieldProps): ReactElement {
    return (
        <FormField {...props} disabled={disabled} name={name}>
            {({ field, ...aria }) => (
                <InputGroup>
                    <InputGroupInput
                        {...field}
                        {...aria}
                        autoComplete="off"
                        inputMode="decimal"
                        placeholder={placeholder}
                        value={field.value ?? ''}
                    />
                    <CurrencySelect
                        currencies={currencies}
                        disabled={disabled}
                        label={currencyLabel}
                        name={currencyName}
                        placeholder={currencyPlaceholder}
                    />
                </InputGroup>
            )}
        </FormField>
    );
}

import type { ReactElement, ReactNode } from 'react';
import { FormField } from '@/components/form/form-field';
import type { FormFieldBaseProps } from '@/components/form/types';
import {
    NumberField,
    NumberFieldDecrement,
    NumberFieldGroup,
    NumberFieldIncrement,
    NumberFieldInput,
} from '@/components/ui/number-field';
import { cn } from '@/lib/utils';

export type NumericFieldKind = 'integer' | 'decimal';

export type NumericFieldProps = FormFieldBaseProps & {
    /** Text before the number, e.g. «от». */
    prefix?: ReactNode;
    /** Text after the number, a unit like «м²» or «до». */
    suffix?: ReactNode;
    /** `integer` keeps whole numbers; `decimal` keeps up to `maxFractionDigits`. */
    kind?: NumericFieldKind;
    maxFractionDigits?: number;
    /** Overrides the floor that `allowNegative` sets. */
    min?: number;
    max?: number;
    /** What the arrow keys and the steppers add. */
    step?: number;
    /** Without it the field floors at 0, unless `min` says otherwise. */
    allowNegative?: boolean;
    /** Shows − and + buttons around the input. */
    showSteppers?: boolean;
    placeholder?: string;
    /** How digits are grouped and which decimal separator is read. */
    locale?: Intl.LocalesArgument;
    inputClassName?: string;
};

function Addon({
    children,
    side,
}: {
    children: ReactNode;
    side: 'start' | 'end';
}): ReactElement {
    return (
        <span
            className={cn(
                'flex shrink-0 select-none items-center text-muted-foreground',
                side === 'start'
                    ? 'ps-[calc(--spacing(3)-1px)]'
                    : 'pe-[calc(--spacing(3)-1px)]',
            )}
        >
            {children}
        </span>
    );
}

/**
 * A number held as a `number`, or `null` while empty. It is parsed and
 * formatted for `locale` («85 000», «54,5»), clamped to `min`/`max` on blur,
 * and rounded to whole numbers for `kind="integer"`.
 */
export function NumericField({
    name,
    label,
    labelAction,
    'aria-label': ariaLabel,
    description,
    className,
    orientation,
    disabled,
    prefix,
    suffix,
    kind = 'decimal',
    maxFractionDigits = 2,
    min,
    max,
    step = 1,
    allowNegative = false,
    showSteppers = false,
    placeholder,
    locale = 'ru-RU',
    inputClassName,
}: NumericFieldProps): ReactElement {
    return (
        <FormField
            aria-label={ariaLabel}
            className={className}
            description={description}
            disabled={disabled}
            label={label}
            labelAction={labelAction}
            name={name}
            orientation={orientation}
        >
            {({ field, id, ...aria }) => (
                <NumberField
                    disabled={field.disabled}
                    format={{
                        maximumFractionDigits:
                            kind === 'integer' ? 0 : maxFractionDigits,
                    }}
                    id={id}
                    locale={locale}
                    max={max}
                    min={min ?? (allowNegative ? undefined : 0)}
                    onValueChange={(value) => {
                        field.onChange(
                            value !== null && kind === 'integer'
                                ? Math.round(value)
                                : value,
                        );
                    }}
                    step={step}
                    value={typeof field.value === 'number' ? field.value : null}
                >
                    <NumberFieldGroup>
                        {showSteppers ? <NumberFieldDecrement /> : null}
                        {prefix ? <Addon side="start">{prefix}</Addon> : null}
                        <NumberFieldInput
                            {...aria}
                            className={cn(
                                !showSteppers && 'text-start',
                                inputClassName,
                            )}
                            onBlur={field.onBlur}
                            placeholder={placeholder}
                            ref={field.ref}
                        />
                        {suffix ? <Addon side="end">{suffix}</Addon> : null}
                        {showSteppers ? <NumberFieldIncrement /> : null}
                    </NumberFieldGroup>
                </NumberField>
            )}
        </FormField>
    );
}

import type { ReactNode } from 'react';
