import type { ComponentProps } from 'react';
import { useEffect, useId, useRef, useState } from 'react';
import { get, useFormState } from 'react-hook-form';
import { Fieldset, FieldsetLegend } from '@/components/ui/fieldset';
import { Input } from '@/components/ui/input';
import { Tabs, TabsList, TabsPanel, TabsTab } from '@/components/ui/tabs';
import { cn } from '@/lib/utils';
import { FormField } from './form-field';
import type { FormFieldBaseProps } from './types';

type OwnedInputProps =
    | 'name'
    | 'id'
    | 'value'
    | 'defaultValue'
    | 'onChange'
    | 'onBlur'
    | 'disabled'
    | 'ref';

export type TranslatableFieldLocale = {
    /** The form path holding this locale's text, e.g. `title_en`. */
    name: string;
    /** Shown on the tab and names the input, e.g. `EN`. */
    label: string;
};

export type TranslatableFieldProps = Omit<
    FormFieldBaseProps,
    'name' | 'labelAction' | 'aria-label' | 'orientation'
> &
    Omit<ComponentProps<typeof Input>, OwnedInputProps> & {
        locales: TranslatableFieldLocale[];
        /** The `name` of the locale shown first. Defaults to the first one. */
        defaultLocale?: string;
    };

/**
 * One text in several languages: a tab per locale, each bound to its own form
 * path. Panels stay mounted, so a locale behind another tab keeps its value
 * and its error. Focusing a locale through react-hook-form (`setFocus`, or the
 * focus on the first invalid field) opens its tab first. When a submission or
 * a 422 rejects a locale while a valid tab is open, the field opens it and
 * focuses the input, unless focus already went to an invalid control elsewhere.
 */
export function TranslatableField({
    label,
    description,
    className,
    disabled,
    locales,
    defaultLocale,
    ...inputProps
}: TranslatableFieldProps) {
    const [activeLocale, setActiveLocale] = useState(
        defaultLocale ?? locales[0]?.name,
    );
    const { errors, isSubmitting } = useFormState();
    const shownLocale = useRef(activeLocale);
    const wasSubmitting = useRef(false);
    const inputs = useRef<Record<string, HTMLInputElement | null>>({});
    const pendingFocus = useRef<string | null>(null);
    const descriptionId = useId();

    const invalidLocales = new Set(
        locales
            .filter((locale) => get(errors, locale.name) !== undefined)
            .map((locale) => locale.name),
    );
    const firstInvalidLocale =
        locales.find((locale) => invalidLocales.has(locale.name))?.name ?? null;
    const isActiveLocaleInvalid = invalidLocales.has(activeLocale);

    function openLocale(name: string, focus: boolean): void {
        if (shownLocale.current === name) {
            if (focus) {
                inputs.current[name]?.focus();
            }

            return;
        }

        pendingFocus.current = focus ? name : null;
        shownLocale.current = name;
        setActiveLocale(name);
    }

    useEffect(() => {
        const finishedSubmitting = wasSubmitting.current && !isSubmitting;

        wasSubmitting.current = isSubmitting;

        if (
            !finishedSubmitting ||
            firstInvalidLocale === null ||
            isActiveLocaleInvalid
        ) {
            return;
        }

        const focused = document.activeElement;
        const focusIsOnInvalidField =
            focused instanceof HTMLElement &&
            focused.getAttribute('aria-invalid') === 'true';

        openLocale(firstInvalidLocale, !focusIsOnInvalidField);
    });

    useEffect(() => {
        if (pendingFocus.current !== activeLocale) {
            return;
        }

        pendingFocus.current = null;
        inputs.current[activeLocale]?.focus();
    }, [activeLocale]);

    return (
        <Fieldset
            aria-describedby={description ? descriptionId : undefined}
            className={cn('flex w-full flex-col gap-2', className)}
            data-slot="translatable-field"
            disabled={disabled}
        >
            <Tabs
                className="gap-2"
                onValueChange={(value) => openLocale(String(value), false)}
                value={activeLocale}
            >
                <div className="flex w-full items-center justify-between gap-2">
                    <FieldsetLegend className="inline-flex items-center gap-2 font-medium text-base/4.5 sm:text-sm/4">
                        {label}
                    </FieldsetLegend>

                    <TabsList size="sm">
                        {locales.map((locale) => (
                            <TabsTab
                                data-invalid={
                                    invalidLocales.has(locale.name) || undefined
                                }
                                key={locale.name}
                                value={locale.name}
                            >
                                {locale.label}
                                {invalidLocales.has(locale.name) ? (
                                    <span
                                        aria-hidden
                                        className="size-1.5 rounded-full bg-destructive"
                                    />
                                ) : null}
                            </TabsTab>
                        ))}
                    </TabsList>
                </div>

                {locales.map((locale) => (
                    <TabsPanel
                        key={locale.name}
                        keepMounted
                        value={locale.name}
                    >
                        <FormField
                            aria-label={locale.label}
                            disabled={disabled}
                            name={locale.name}
                        >
                            {({ field, ...aria }) => (
                                <Input
                                    {...inputProps}
                                    {...field}
                                    // react-hook-form focuses a field through
                                    // the ref it was given. Handing it a proxy
                                    // lets that focus open the tab first.
                                    ref={(input) => {
                                        inputs.current[locale.name] = input;
                                        field.ref(
                                            input
                                                ? {
                                                      focus: () =>
                                                          openLocale(
                                                              locale.name,
                                                              true,
                                                          ),
                                                  }
                                                : null,
                                        );
                                    }}
                                    value={field.value ?? ''}
                                    {...aria}
                                />
                            )}
                        </FormField>
                    </TabsPanel>
                ))}
            </Tabs>

            {description ? (
                <p
                    className="text-muted-foreground text-xs"
                    data-slot="field-description"
                    id={descriptionId}
                >
                    {description}
                </p>
            ) : null}
        </Fieldset>
    );
}

import type { ReactNode } from 'react';
import type { ControllerRenderProps, FieldValues } from 'react-hook-form';

export type FieldOrientation = 'vertical' | 'horizontal' | 'responsive';

/**
 * Attributes that tie a control to its label, description and error message.
 * `FormField` builds them; every field component must spread them onto its control.
 */
export type FieldControlProps = {
    id: string;
    /** Omitted while the field is valid: `aria-invalid="false"` still matches
     * attribute-presence selectors and would paint the control as invalid. */
    'aria-invalid': true | undefined;
    'aria-describedby': string | undefined;
    'aria-label': string | undefined;
};

export type FormFieldRenderArgs = FieldControlProps & {
    field: ControllerRenderProps<FieldValues, string>;
};

export type FormFieldBaseProps = {
    name: string;
    label?: ReactNode;
    /**
     * Rendered on the label's row but outside the `<label>` element, for things
     * like a "Forgot your password?" link. Interactive content may not be nested
     * inside a label, so it cannot simply be part of `label`.
     */
    labelAction?: ReactNode;
    /** Names the control when the surrounding page already shows the label as a heading. */
    'aria-label'?: string;
    description?: ReactNode;
    className?: string;
    orientation?: FieldOrientation;
    disabled?: boolean;
};

export type FieldOption = {
    value: string;
    label: ReactNode;
    disabled?: boolean;
};

/** Shape produced by a Wayfinder route helper, e.g. `store()` or `ProfileController.update()`. */
export type FormAction = {
    url: string;
    method: 'get' | 'post' | 'put' | 'patch' | 'delete';
};

import { useEffect, useEffectEvent, useState } from 'react';

export type AsyncOptionsSearch<TOption> = (
    query: string,
    options: { signal: AbortSignal },
) => Promise<TOption[]>;

export type UseAsyncOptionsOptions<TOption> = {
    /**
     * Fetches the options for a query. The signal aborts when a newer query
     * supersedes this one; pass it to `fetch` (or ignore it — a late answer
     * is dropped either way). Read on every call, so an inline function does
     * not restart the search.
     */
    search: AsyncOptionsSearch<TOption>;
    /** Wait after the last keystroke before searching. */
    debounceMs?: number;
    /** Shorter queries do not search; the options are cleared instead. */
    minQueryLength?: number;
    /** Searches for an empty query too: a short dictionary, not a catalogue of streets. */
    loadWithoutQuery?: boolean;
    /** Nothing is searched while false, e.g. while a popup is closed. The last options stay. */
    enabled?: boolean;
    /** Changing it drops the options and searches again, e.g. another city for its streets. */
    scope?: string | number | null;
};

export type AsyncOptionsStatus = 'idle' | 'loading' | 'success' | 'error';

export type AsyncOptions<TOption> = {
    options: TOption[];
    query: string;
    setQuery: (query: string) => void;
    /** `idle` while the query is too short to search. */
    status: AsyncOptionsStatus;
    isLoading: boolean;
    /** What the last search threw; `null` after a success. */
    error: unknown;
};

/**
 * Debounced options for a typed query. Only the latest query wins: the
 * previous request is aborted and its answer, if it still arrives, ignored.
 */
export function useAsyncOptions<TOption>({
    search,
    debounceMs = 300,
    minQueryLength = 1,
    loadWithoutQuery = false,
    enabled = true,
    scope = null,
}: UseAsyncOptionsOptions<TOption>): AsyncOptions<TOption> {
    const [query, setQuery] = useState('');
    const [options, setOptions] = useState<TOption[]>([]);
    const [status, setStatus] = useState<AsyncOptionsStatus>('idle');
    const [error, setError] = useState<unknown>(null);
    const [loadedScope, setLoadedScope] = useState(scope);
    const runSearch = useEffectEvent(
        (typed: string, signal: AbortSignal): Promise<TOption[]> =>
            search(typed, { signal }),
    );

    const trimmed = query.trim();
    const isSearchable =
        trimmed === ''
            ? loadWithoutQuery
            : trimmed.length >= Math.max(minQueryLength, 1);

    // Options of another scope would offer a street of another city.
    if (loadedScope !== scope) {
        setLoadedScope(scope);
        setOptions([]);
    }

    // biome-ignore lint/correctness/useExhaustiveDependencies: a new scope searches again; runSearch is an effect event
    useEffect(() => {
        if (!enabled) {
            setStatus((current) => (current === 'loading' ? 'idle' : current));

            return;
        }

        if (!isSearchable) {
            setOptions([]);
            setStatus('idle');
            setError(null);

            return;
        }

        const controller = new AbortController();

        setStatus('loading');

        const timer = setTimeout(
            () => {
                runSearch(trimmed, controller.signal).then(
                    (found) => {
                        if (!controller.signal.aborted) {
                            setOptions(found);
                            setError(null);
                            setStatus('success');
                        }
                    },
                    (reason: unknown) => {
                        if (!controller.signal.aborted) {
                            setError(reason);
                            setStatus('error');
                        }
                    },
                );
            },
            trimmed === '' ? 0 : debounceMs,
        );

        return () => {
            clearTimeout(timer);
            controller.abort();
        };
    }, [enabled, isSearchable, trimmed, debounceMs, scope]);

    return {
        error,
        isLoading: status === 'loading',
        options,
        query,
        setQuery,
        status,
    };
}

import { zodResolver } from '@hookform/resolvers/zod';
import type { RequestPayload, VisitOptions } from '@inertiajs/core';
import { router } from '@inertiajs/react';
import type { BaseSyntheticEvent } from 'react';
import { useState } from 'react';
import type {
    DefaultValues,
    FieldPath,
    FieldValues,
    Resolver,
    UseFormProps,
    UseFormReturn,
} from 'react-hook-form';
import { useForm } from 'react-hook-form';
import type { ZodType, z } from 'zod';
import { collectFieldPaths, isKnownFieldPath } from './field-paths';
import type { FormAction } from './types';

type ManagedVisitOptions = Omit<
    VisitOptions,
    'method' | 'data' | 'onError' | 'onSuccess' | 'onFinish'
>;

/**
 * Both are derived from the schema rather than exposed as type parameters:
 * a parameter would give TypeScript a second inference site — `resetOnSuccess`,
 * for one — and the values would be inferred from the wrong prop.
 */
export type SchemaInput<TSchema extends ZodType<unknown, FieldValues>> =
    z.input<TSchema> & FieldValues;

export type SchemaOutput<TSchema extends ZodType<unknown, FieldValues>> =
    z.output<TSchema>;

export type UseInertiaFormOptions<
    TSchema extends ZodType<unknown, FieldValues>,
> = {
    action: FormAction;
    schema: TSchema;
    defaultValues: DefaultValues<SchemaInput<TSchema>>;
    /**
     * Omitted: reset to the submitted values, clearing the dirty state but keeping the input.
     * `false`: leave the form untouched. `true`: reset every field to its default.
     * An array resets only the listed fields, mirroring Inertia's `<Form resetOnSuccess>`.
     */
    resetOnSuccess?: boolean | Array<FieldPath<SchemaInput<TSchema>>>;
    transform?: (values: SchemaOutput<TSchema>) => Record<string, unknown>;
    onSuccess?: () => void;
    onError?: (errors: Record<string, string>) => void;
    visit?: ManagedVisitOptions;
    mode?: UseFormProps['mode'];
    reValidateMode?: UseFormProps['reValidateMode'];
};

/** Named to stay clear of `InertiaForm`, which `@inertiajs/react` already exports. */
export type InertiaFormReturn<
    TInput extends FieldValues,
    TOutput = TInput,
> = UseFormReturn<TInput, unknown, TOutput> & {
    submit: (event?: BaseSyntheticEvent) => void;
    fieldPaths: Set<string>;
};

/**
 * Inertia delivers a named error bag as one nesting level keyed by the bag name.
 * Laravel's own nested fields arrive as flat dotted keys, so an object value can
 * only be a bag and its name is dropped.
 */
function flattenErrorBags(
    errors: Record<string, unknown>,
): Record<string, string> {
    const flattened: Record<string, string> = {};

    for (const [key, value] of Object.entries(errors)) {
        if (typeof value === 'string') {
            flattened[key] = value;

            continue;
        }

        if (typeof value === 'object' && value !== null) {
            Object.assign(
                flattened,
                flattenErrorBags(value as Record<string, unknown>),
            );
        }
    }

    return flattened;
}

/**
 * Laravel returns 422 errors keyed by field. Keys that match a field are shown
 * next to it; anything else — a throttle message, for example — would otherwise
 * vanish, so it lands under `root` where the form renders it as a top level alert.
 * Returns the first field that was rejected, for focusing.
 */
function applyServerErrors<TInput extends FieldValues, TOutput>(
    form: UseFormReturn<TInput, unknown, TOutput>,
    errors: Record<string, string>,
    fieldPaths: Set<string>,
): string | null {
    let firstRejectedField: string | null = null;

    for (const [key, message] of Object.entries(flattenErrorBags(errors))) {
        if (isKnownFieldPath(fieldPaths, key)) {
            form.setError(key as FieldPath<TInput>, {
                type: 'server',
                message,
            });

            firstRejectedField ??= key;

            continue;
        }

        form.setError(`root.${key}`, { type: 'server', message });
    }

    return firstRejectedField;
}

/**
 * Moves focus to the first field the server rejected. react-hook-form's own
 * `setFocus` does not reach a Controller's ref once `setError` has run, so the
 * control is looked up by the name it renders and focused directly.
 */
function focusRejectedField(
    form: HTMLFormElement | null,
    name: string | null,
): void {
    if (form === null || name === null) {
        return;
    }

    const control = form.querySelector<HTMLElement>(
        `[name="${CSS.escape(name)}"]`,
    );

    control?.focus();
}

export function useInertiaForm<
    TSchema extends ZodType<unknown, FieldValues>,
    TInput extends FieldValues = SchemaInput<TSchema>,
    TOutput = SchemaOutput<TSchema>,
>({
    action,
    schema,
    defaultValues,
    resetOnSuccess,
    transform,
    onSuccess,
    onError,
    visit,
    mode = 'onTouched',
    reValidateMode = 'onChange',
}: UseInertiaFormOptions<TSchema>): InertiaFormReturn<TInput, TOutput> {
    const form = useForm<TInput, unknown, TOutput>({
        resolver: zodResolver(schema) as unknown as Resolver<
            TInput,
            unknown,
            TOutput
        >,
        defaultValues: defaultValues as DefaultValues<TInput>,
        mode,
        reValidateMode,
    });

    // The shape of the defaults never changes at runtime, so deriving the paths
    // once keeps the context value stable across renders.
    const [fieldPaths] = useState(() => collectFieldPaths(defaultValues));

    const submit = form.handleSubmit((values, event) => {
        // The submit event carries the form element, which is what scopes the
        // lookup when focusing a rejected field. A page may hold several forms.
        const formElement = (event?.target as HTMLFormElement | null) ?? null;

        const data = transform
            ? transform(values as SchemaOutput<TSchema>)
            : (values as RequestPayload);

        // router.visit is callback based. Without wrapping it, handleSubmit
        // resolves immediately and formState.isSubmitting flips back to false
        // while the request is still in flight, un-disabling the submit button.
        return new Promise<void>((resolve) => {
            router.visit(action.url, {
                ...visit,
                method: action.method,
                data: data as RequestPayload,
                onError: (serverErrors) => {
                    const rejected = applyServerErrors(
                        form,
                        serverErrors,
                        fieldPaths,
                    );

                    focusRejectedField(formElement, rejected);
                    onError?.(serverErrors);
                },
                onSuccess: () => {
                    if (resetOnSuccess === false) {
                        onSuccess?.();

                        return;
                    }

                    if (resetOnSuccess === true) {
                        form.reset();
                    } else if (Array.isArray(resetOnSuccess)) {
                        for (const field of resetOnSuccess) {
                            form.resetField(field as FieldPath<TInput>);
                        }
                    } else {
                        form.reset(form.getValues());
                    }

                    onSuccess?.();
                },
                onFinish: () => {
                    resolve();
                },
            });
        });
    });

    return { ...form, submit, fieldPaths };
}
